			continue // covered by activity_columns_test.go
		case "Model":
			if !got(zero) || got(full) {
				t.Error("Model: only the placeholder is dim")
			}
		default:
			if !got(zero) || got(full) {
				t.Errorf("%s: only a zero is dim", col.Title)
			}
		}
	}
}

